  const cooldown=dungeon.entrances.find(entrance=>entrance.cooldownMinutes!==null)?.cooldownMinutes??null;
  const entranceCards=dungeon.entrances.length?`<div class="dungeon-entrance-grid">${dungeon.entrances.map((entrance,index)=>`<a class="dungeon-entrance" href="${href("/map")}?layers=dungeon&dungeon=${encodeURIComponent(dungeon.slug)}&world=${entrance.worldId}" data-link><strong>${copy.entrances} ${(index+1).toLocaleString(locale)}</strong><small>X ${Math.round(entrance.map.x).toLocaleString(locale)} · Y ${Math.round(entrance.map.y).toLocaleString(locale)}</small><span>${copy.openMap}</span></a>`).join("")}</div>`:`<p class="notice">${esc(copy.noEntrance)}</p>`;
