function npcKindLabel(npc:Npc){const copy=npcCopy[locale];return npc.kind==="merchant"?copy.merchant:npc.kind==="reward"?copy.rewardNpc:npc.kind==="request"?copy.requestNpc:npc.kind==="quest"?copy.questNpc:npc.kind==="guide"?copy.guideNpc:npc.kind==="combat"?copy.combatNpc:copy.characterNpc}
function npcDescription(npc:Npc){const copy=npcCopy[locale];return npc.merchant?.type==="items"||npc.merchant?.type==="item-profiles"?copy.itemMerchantDescription:npc.merchant?.type==="pals"?copy.palMerchantDescription:npc.events?.type==="achievement"?copy.achievementDescription:npc.events?.type==="item-request"?copy.foodDescription:npc.events?.type==="pal-request"?copy.palCriticDescription:npc.kind==="merchant"?copy.stockUnavailable:npc.kind==="quest"?copy.questDescription:npc.kind==="guide"?copy.guideDescription:npc.kind==="combat"?copy.combatDescription:npc.kind==="reward"?copy.rewardDescription:copy.characterDescription}
function npcCollectionPage(){const copy=npcCopy[locale],npcs=[...(npcData?.npcs||[])].sort((a,b)=>new Intl.Collator(locale,{numeric:true}).compare(npcName(a),npcName(b))||a.slug.localeCompare(b.slug));setMeta(copy.catalogTitle,copy.catalogIntro);return `${hero(copy.catalogTitle,copy.catalogIntro)}<section class="section">${databaseTabs("npcs")}<p class="collection-intro">${esc(copy.catalogIntro)}</p><div class="collection-filters npc-filters"><label class="collection-search">${copy.search}<input id="npc-search" type="search" autocomplete="off"></label><label>${copy.roles}<select id="npc-kind"><option value="">${copy.all}</option><option value="merchant">${copy.merchant}</option><option value="quest">${copy.questNpc}</option><option value="reward">${copy.rewardNpc}</option><option value="request">${copy.requestNpc}</option><option value="guide">${copy.guideNpc}</option><option value="combat">${copy.combatNpc}</option><option value="character">${copy.characterNpc}</option></select></label><button class="button search-clear" data-clear-search="npc" aria-label="${m.remove}">×</button></div><p id="npc-count" role="status">${npcs.length.toLocaleString(locale)} ${m.results}</p><p id="npc-empty" class="empty-compact" hidden>${copy.noResults}</p><div class="npc-grid">${npcs.map(npc=>{const search=[npc.slug,...Object.values(npc.names),...npc.roles.map(npcRoleLabel)].join(" ").toLocaleLowerCase(locale),locationText=npc.fixedLocation?`${copy.fixedLocations}: ${npc.encounters.length.toLocaleString(locale)}`:copy.noFixedLocation,level=npc.level?` · ${copy.level} ${npc.level.min===npc.level.max?npc.level.min.toLocaleString(locale):`${npc.level.min.toLocaleString(locale)}–${npc.level.max.toLocaleString(locale)}`}`:"";return `<article class="npc-card panel" data-npc="${esc(search)}" data-kind="${npc.kind}"><img src="/assets/map-icons/${npc.kind==="merchant"?"merchant":npc.kind==="combat"?"wanted":"npc"}.webp" alt="" width="64" height="64"><div><p class="npc-kind">${esc(npcKindLabel(npc))}</p><h2><a href="${href(`/database/npcs/${npc.slug}`)}" data-link>${esc(npcName(npc))}</a></h2><p>${esc(npcDescription(npc))}</p><p class="work-tags">${[...new Set(npc.roles.map(npcRoleLabel))].map(role=>`<span>${esc(role)}</span>`).join("")}</p><small>${esc(locationText+level)}</small></div></article>`}).join("")}</div></section>`}
function rewardLinks(rewards:NpcReward[]){const byId=new Map(itemData?.items.map(item=>[item.id,item])||[]);return rewards.map(reward=>{const item=byId.get(reward.itemId);return item?`<a class="npc-reward" href="${href(`/items/${encodeURIComponent(item.id)}`)}" data-link>${item.image?`<img src="/assets/items/${encodeURIComponent(item.id)}.webp" alt="" width="36" height="36" loading="lazy">`:""}<span>${esc(itemName(item))} × ${reward.quantity.toLocaleString(locale)}</span></a>`:""}).join("")}
function npcRequirement(npc:Npc,step:NpcEventStep){const copy=npcCopy[locale];if(npc.events?.type==="achievement"){const template=npc.events.category==="paldex"?copy.paldexRequirement:npc.events.category==="capture"?copy.captureRequirement:copy.bossRequirement;return formatNpcCopy(template,{count:(step.requireCount||0).toLocaleString(locale)})}if(npc.events?.type==="item-request"){const item=itemData?.items.find(entry=>entry.id===step.requestItemId);return item?formatNpcCopy(copy.itemRequirement,{quantity:(step.requestQuantity||0).toLocaleString(locale),name:itemName(item)}):copy.loading}const pal=data?.pals.find(entry=>entry.id===step.requestPalId);return pal?formatNpcCopy(copy.palRequirement,{name:palName(pal)}):copy.loading}
function npcVariantNumber(variant:string|undefined,fallback:number){return variant&&/^[A-Z]$/.test(variant)?variant.charCodeAt(0)-64:fallback}
function npcEventRows(npc:Npc){const copy=npcCopy[locale],steps=npc.events?.steps||[],variantSteps=new Map<string,number>();return steps.map((step,index)=>{const stepNumber=step.variant?(variantSteps.set(step.variant,(variantSteps.get(step.variant)||0)+1),variantSteps.get(step.variant)!):index+1,location=step.variant?`${formatNpcCopy(copy.locationNumber,{number:npcVariantNumber(step.variant,index+1).toLocaleString(locale)})} · `:"";return `<tr><td>${esc(location+copy.step)} ${stepNumber.toLocaleString(locale)}</td><td>${esc(npcRequirement(npc,step))}</td><td><div class="npc-rewards">${rewardLinks(step.rewards)}</div></td></tr>`}).join("")||`<tr><td colspan="3">${m.noResult}</td></tr>`}
function npcOfferTable(offers:NpcOffer[],itemsById:Map<string,Item>){const copy=npcCopy[locale];return `<div class="table-wrap"><table class="npc-table"><thead><tr><th>${copy.soldItems}</th><th>${copy.quantity}</th><th>${copy.price}</th></tr></thead><tbody>${offers.map(offer=>{const item=itemsById.get(offer.itemId);return item?`<tr><td><a class="npc-shop-item" href="${href(`/items/${encodeURIComponent(item.id)}`)}" data-link>${item.image?`<img src="/assets/items/${encodeURIComponent(item.id)}.webp" alt="" width="40" height="40" loading="lazy">`:""}<span>${esc(itemName(item))}${offer.purchaseLimit==="once"?`<small>${copy.oneTime}</small>`:""}</span></a></td><td>${offer.quantity.toLocaleString(locale)}</td><td>${offer.price.toLocaleString(locale)}</td></tr>`:""}).join("")}</tbody></table></div>`}
function npcCurrency(currencyItemId:string,itemsById:Map<string,Item>){const copy=npcCopy[locale],currency=itemsById.get(currencyItemId);return `<p class="npc-currency"><strong>${copy.currency}</strong> ${currency?`<a href="${href(`/items/${encodeURIComponent(currency.id)}`)}" data-link>${esc(itemName(currency))}</a>`:esc(copy.loading)}</p>`}
function npcDetail(slug:string):string{
  if(!itemData)ensureItemData();
  if(!data)ensurePalData();
  const npc=npcData?.npcs.find(entry=>entry.slug===slug),copy=npcCopy[locale];
  if(!npc){if(npcData)return placeholder("404");return ""}
  const description=npcDescription(npc),itemsById=new Map(itemData?.items.map(item=>[item.id,item])||[]),palsById=new Map(data?.pals.map(pal=>[pal.id,pal])||[]);
  setMeta(npcName(npc),description);
  const encounters=[...npc.encounters].sort((a,b)=>a.variant&&b.variant?a.variant.localeCompare(b.variant):a.variant?-1:b.variant?1:0);
  const locationList=encounters.length?`<section class="detail-section npc-locations"><h2>${copy.locations}</h2><p>${copy.fixedLocations}: ${encounters.length.toLocaleString(locale)}</p><div class="npc-location-grid">${encounters.map((encounter,index)=>{const coordinate=gameMapCoordinates(encounter.x,encounter.y),label=formatNpcCopy(copy.locationNumber,{number:npcVariantNumber(encounter.variant,index+1).toLocaleString(locale)});return `<a class="npc-location" href="${href("/map")}?layers=npc,merchant,palMerchant,bounty&npc=${encodeURIComponent(npc.slug)}" data-link><strong>${esc(label)}</strong><small>X ${Math.round(coordinate.x).toLocaleString(locale)} · Y ${Math.round(coordinate.y).toLocaleString(locale)}</small><span>${copy.openMap}</span></a>`}).join("")}</div></section>`:`<section class="detail-section npc-locations"><h2>${copy.locations}</h2><p class="notice">${copy.noFixedLocation}</p></section>`;
  let capability="";
  if(npc.merchant?.type==="items")capability=`<section class="detail-section"><h2>${copy.soldItems}</h2>${npcCurrency(npc.merchant.currencyItemId,itemsById)}${npcOfferTable(npc.merchant.offers,itemsById)}</section>`;
  else if(npc.merchant?.type==="item-profiles")capability=`<section class="detail-section"><h2>${copy.soldItems}</h2>${npcCurrency(npc.merchant.currencyItemId,itemsById)}<div class="npc-shop-profiles">${npc.merchant.profiles.map((profile,index)=>`<article class="panel"><h3>${copy.shopProfile} ${(index+1).toLocaleString(locale)}</h3>${npcOfferTable(profile.offers,itemsById)}</article>`).join("")}</div></section>`;
  else if(npc.merchant?.type==="pals")capability=`<section class="detail-section"><h2>${copy.palStock}</h2><p>${copy.stockRule}</p><div class="npc-pal-profiles">${npc.merchant.profiles.map((profile,index)=>`<article class="panel"><h3>${copy.shopProfile} ${(index+1).toLocaleString(locale)} · ${copy.levelRange}: ${profile.minLevel}–${profile.maxLevel}</h3><div class="relation-list entity-relation-list">${profile.palIds.map(id=>{const pal=palsById.get(id);return pal?`<a href="${href(`/pals/${encodeURIComponent(pal.id)}`)}" data-link>${pal.image?`<img src="/assets/pals/${encodeURIComponent(pal.id)}.png" alt="" loading="lazy">`:""}<span><strong>${esc(palName(pal))}</strong><small>#${pal.dex}${pal.variant?"B":""}</small></span></a>`:""}).join("")}</div></article>`).join("")}</div></section>`;
  else if(npc.events)capability=`<section class="detail-section"><h2>${copy.events}</h2><div class="table-wrap"><table class="npc-table npc-event-table"><thead><tr><th>${copy.step}</th><th>${copy.requirement}</th><th>${copy.rewards}</th></tr></thead><tbody>${npcEventRows(npc)}</tbody></table></div></section>`;
  else if(npc.roles.some(role=>role==="item-shop"||role==="pal-shop"))capability=`<section class="detail-section"><h2>${copy.soldItems}</h2><p class="notice">${copy.stockUnavailable}</p></section>`;
  const level=npc.level?`<p><strong>${copy.level}</strong> ${npc.level.min===npc.level.max?npc.level.min.toLocaleString(locale):`${npc.level.min.toLocaleString(locale)}–${npc.level.max.toLocaleString(locale)}`}</p>`:"";
  return `${hero(npcName(npc),description)}<article class="npc-detail section"><div class="npc-summary panel"><img src="/assets/map-icons/${npc.kind==="merchant"?"merchant":npc.kind==="combat"?"wanted":"npc"}.webp" alt="" width="96" height="96"><div><p class="npc-kind">${esc(npcKindLabel(npc))}</p><p class="entity-description">${esc(description)}</p>${level}<h2>${copy.roles}</h2><p class="work-tags">${[...new Set(npc.roles.map(npcRoleLabel))].map(role=>`<span>${esc(role)}</span>`).join("")}</p></div></div>${locationList}${capability}</article>`;
}
function skillsPage(groupPassive=false){const labels=skillLabels[locale],localized=(names:Record<Locale,string>)=>names[locale]||names[defaultLocale],elements=skillData?.elements||[],active=skillData?.activeSkills||[],collator=new Intl.Collator(locale,{numeric:true}),passive=[...(skillData?.passiveSkills||[])].sort((a,b)=>b.rank-a.rank||collator.compare(localized(a.names),localized(b.names))||a.id.localeCompare(b.id));setMeta(labels.title,`${labels.active} · ${labels.passive}`);const elementById=new Map(elements.map(element=>[element.id,element]));const activeCards=(groupPassive?[]:active).map(skill=>{const element=elementById.get(skill.elementId),search=[skill.id,skill.elementId,...Object.values(skill.names),...(element?Object.values(element.names):[])].join(" ").toLocaleLowerCase(locale);return `<article class="skill-card" data-skill="${esc(search)}" data-kind="active" data-element="${esc(skill.elementId)}"><div class="skill-card-head"><img src="${esc(element?.icon||`/assets/elements/${skill.elementId}.svg`)}" alt="${esc(element?localized(element.names):skill.elementId)}" width="56" height="56"><div><h2><a class="skill-name-link" href="${href(`/skills/active/${encodeURIComponent(skill.id)}`)}" data-link>${esc(localized(skill.names))}</a></h2></div></div><p class="work-tags"><span>${esc(element?localized(element.names):skill.elementId)}</span><span>${labels.power} ${skill.power}</span><span>${labels.cooldown} ${skill.cooldown}</span>${skill.canInherit?`<span>${labels.inherit}</span>`:""}</p></article>`}).join("");const passiveCard=(skill:PassiveSkill)=>{const search=[skill.id,...Object.values(skill.names),...Object.values(skill.descriptions)].join(" ").toLocaleLowerCase(locale);return `<article class="skill-card passive-skill" data-skill="${esc(search)}" data-kind="passive" data-element="" data-rank="${skill.rank}"><div class="skill-card-head"><span class="passive-rank" aria-hidden="true">${skill.rank>=0?"+":""}${skill.rank}</span><div><h2><a class="skill-name-link" href="${href(`/skills/passive/${encodeURIComponent(skill.id)}`)}" data-link>${esc(localized(skill.names))}</a></h2></div></div><p>${esc(localized(skill.descriptions))}</p><p class="work-tags">${skill.randomInheritanceAllowed?`<span>${labels.inherit}</span>`:""}</p></article>`};const passiveCards=passive.map(passiveCard).join(""),rankOrder=[5,4,3,2,1,-1,-2,-3],passiveContent=groupPassive?`<div class="passive-rank-groups">${rankOrder.map(rank=>{const skills=passive.filter(skill=>skill.rank===rank),rankText=`${rank>0?"+":""}${rank}`;return `<section class="passive-rank-group rank-${rank>0?"positive":"negative"}" data-passive-group="${rank}"><header class="passive-rank-heading"><img src="/assets/passive-ranks/${rank}.png" alt="" width="44" height="44"><h2>${esc(passiveUiLabels[locale].rank)} ${rankText}</h2><span data-rank-count="${rank}">${skills.length.toLocaleString(locale)} ${m.results}</span></header><div class="skill-grid">${skills.map(passiveCard).join("")}</div></section>`}).join("")}</div>`:`<div class="skill-grid">${activeCards}${passiveCards}</div>`;return `${hero(labels.title,`${labels.active} · ${labels.passive}`)}<section class="section"><div class="element-strip" aria-label="${labels.elements}">${elements.map(element=>`<button type="button" data-element-button="${esc(element.id)}"><img src="${esc(element.icon)}" alt="" width="40" height="40"><span>${esc(localized(element.names))}</span></button>`).join("")}</div><div class="collection-filters"><label class="collection-search">${labels.search}<input id="skill-search" type="search" autocomplete="off"></label><label>${labels.title}<select id="skill-kind"><option value="">${labels.all}</option><option value="active">${labels.active}</option><option value="passive">${labels.passive}</option></select></label><label>${labels.elements}<select id="skill-element"><option value="">${labels.all}</option>${elements.map(element=>`<option value="${esc(element.id)}">${esc(localized(element.names))}</option>`).join("")}</select></label>${groupPassive?`<label>${esc(passiveUiLabels[locale].rank)}<select id="skill-rank"><option value="">${esc(labels.all)}</option>${rankOrder.map(rank=>`<option value="${rank}">${rank>0?"+":""}${rank}</option>`).join("")}</select></label>`:""}<button class="button search-clear" data-clear-search="skill" aria-label="${m.remove}">×</button></div><p id="skill-count" role="status">${(groupPassive?passive.length:active.length+passive.length).toLocaleString(locale)} ${m.results}</p><p id="skill-empty" class="empty-compact" hidden>${m.noResult}</p>${passiveContent}</section>`}
function skillDetail(kind:string,segment:string){const labels=skillLabels[locale],extra=uiCopy[locale],localized=(names:Record<Locale,string>)=>names[locale]||names[defaultLocale];if(kind==="active"){const skill=skillData?resolveEntitySegment("activeSkills",segment,skillData.activeSkills,"skills/active"):null,element=skillData?.elements.find(entry=>entry.id===skill?.elementId);if(!skill)return placeholder("404");const description=localized(skill.descriptions);setMeta(localized(skill.names),description||labels.active);return `${hero(localized(skill.names),labels.active)}<article class="entity-detail panel"><img class="detail-image element-detail" src="${esc(element?.icon||"")}" alt="${esc(element?localized(element.names):skill.elementId)}"><div class="entity-detail-content">${description?`<p class="entity-description">${esc(description)}</p>`:""}<dl class="detail-stats"><div><dt>${labels.elements}</dt><dd>${esc(element?localized(element.names):skill.elementId)}</dd></div><div><dt>${labels.power}</dt><dd>${skill.power}</dd></div><div><dt>${labels.cooldown}</dt><dd>${skill.cooldown}</dd></div><div><dt>${labels.inherit}</dt><dd>${skill.canInherit?m.yes:m.no}</dd></div><div><dt>${extra.skillFruit}</dt><dd>${skill.hasSkillFruit?m.yes:m.no}</dd></div></dl></div></article>`}const skill=skillData?resolveEntitySegment("passiveSkills",segment,skillData.passiveSkills,"skills/passive"):null;if(!skill)return placeholder("404");const description=localized(skill.descriptions);setMeta(localized(skill.names),description||labels.passive);return `${hero(localized(skill.names),labels.passive)}<article class="entity-detail panel"><span class="detail-image passive-rank">${skill.rank>=0?"+":""}${skill.rank}</span><div class="entity-detail-content"><p class="entity-description">${esc(description)}</p><dl class="detail-stats"><div><dt>${labels.inherit}</dt><dd>${skill.randomInheritanceAllowed?m.yes:m.no}</dd></div><div><dt>${passiveUiLabels[locale].surgery}</dt><dd>${skill.surgeryCost.toLocaleString(locale)}</dd></div></dl></div></article>`}
function palDetail(segment:string){const pal=data?resolveEntitySegment("pals",segment,data.pals,"pals"):null;if(!pal){setMeta("404");return placeholder("404")}const description=palDescription(pal),metaDescription=description||m.palDexBody;setMeta(palName(pal),metaDescription);const labels=skillLabels[locale],extra=uiCopy[locale],passiveById=new Map(skillData?.passiveSkills.map(skill=>[skill.id,skill])||[]),localized=(names:Record<Locale,string>)=>names[locale]||names[defaultLocale];return `${hero(palName(pal),metaDescription)}<article class="entity-detail pal-detail panel">${pal.image?`<img class="detail-image" src="/assets/pals/${encodeURIComponent(pal.id)}.png" alt="${esc(palName(pal))}">`:`<div class="detail-image item-fallback" aria-hidden="true">◇</div>`}<div><p class="pal-number">#${pal.dex}${pal.variant?"B":""}</p>${palElementBadges(pal)}${description?`<p class="entity-description pal-lore">${esc(description)}</p>`:""}<dl class="detail-stats"><div><dt>${m.hp}</dt><dd>${pal.hp}</dd></div><div><dt>${m.attack}</dt><dd>${pal.attack}</dd></div><div><dt>${m.defense}</dt><dd>${pal.defense}</dd></div><div><dt>${m.rarity}</dt><dd>${pal.rarity}</dd></div><div><dt>${extra.size}</dt><dd>${esc(pal.size)}</dd></div><div><dt>${extra.breedingPower}</dt><dd>${pal.power.toLocaleString(locale)}</dd></div><div><dt>${m.nocturnal}</dt><dd>${pal.nocturnal?m.yes:m.no}</dd></div></dl><h2>${m.work}</h2><div class="work-suitability-list detail-work-list">${workSuitabilityBadges(pal.work)}</div>${pal.guaranteedPassiveIds.length?`<section class="pal-passives"><h2>${labels.passive}</h2>${pal.guaranteedPassiveIds.map(passiveId=>{const passive=passiveById.get(passiveId);return passive?`<article><strong><a href="${href(`/skills/passive/${encodeURIComponent(passive.id)}`)}" data-link>${esc(localized(passive.names))}</a></strong><p>${esc(localized(passive.descriptions))}</p></article>`:""}).join("")}</section>`:""}${renderPalDropSection(pal)}${renderPalDungeonSection(pal)}<div class="detail-actions"><a class="button primary" href="${href("/calculators/breeding")}" data-link>${m.openBreed}</a><a class="button" href="${href(`/map?pal=${encodeURIComponent(pal.id)}`)}" data-link>${m.map}</a></div></div></article>`}
function itemDetail(segment:string){const item=itemData?resolveEntitySegment("items",segment,itemData.items,"items"):null;if(!item){setMeta("404");return placeholder("404")}setMeta(itemName(item),item.descriptions?.[locale]||m.itemDatabaseBody);const recipes=itemData?.recipes.filter(r=>r.productId===item.id)||[],usedIn=itemData?.recipes.filter(r=>r.ingredients.some(ingredient=>ingredient.itemId===item.id))||[],byId=new Map(itemData?.items.map(i=>[i.id,i])||[]),unlocked=item.unlocksItemId?byId.get(item.unlocksItemId):undefined;return `${hero(itemName(item))}<article class="entity-detail item-detail panel">${itemVisual(item,{detail:true})}<div class="entity-detail-content"><p class="entity-description">${esc(item.descriptions?.[locale]||m.itemDatabaseBody)}</p>${unlocked?`<p><a class="button" href="${href(`/items/${encodeURIComponent(unlocked.id)}`)}" data-link>${unlocked.image?`<img src="/assets/items/${encodeURIComponent(unlocked.id)}.webp" alt="" width="32" height="32">`:""}${esc(itemName(unlocked))}</a></p>`:""}<p class="work-tags item-categories"><span>${esc(itemCategoryLabel(item.type,locale))}</span></p><dl class="detail-stats"><div><dt>${m.rank}</dt><dd>${item.rank}</dd></div><div><dt>${m.rarity}</dt><dd>${item.rarity}</dd></div><div><dt>${m.stack}</dt><dd>${item.maxStack.toLocaleString(locale)}</dd></div><div><dt>${m.weight}</dt><dd>${item.weight.toLocaleString(locale)}</dd></div><div><dt>${m.price}</dt><dd>${item.price.toLocaleString(locale)}</dd></div></dl>${renderItemDropSection(item)}${renderItemDungeonSection(item)}${renderItemExpeditionSection(item)}${recipes.length?`<section class="detail-section"><h2>${m.crafting}</h2>${recipes.map(r=>`<article class="relation-card"><ul>${r.ingredients.map(i=>`<li><a href="${href(`/items/${encodeURIComponent(i.itemId)}`)}" data-link>${esc(itemName(byId.get(i.itemId)!))}</a> × ${i.count.toLocaleString(locale)}</li>`).join("")}</ul></article>`).join("")}</section>`:""}${usedIn.length?`<section class="detail-section"><h2>${usedIn.length.toLocaleString(locale)} ${m.results}</h2><div class="relation-list">${usedIn.map(recipe=>{const product=byId.get(recipe.productId);return product?`<a href="${href(`/items/${encodeURIComponent(product.id)}`)}" data-link>${product.image?`<img src="/assets/items/${encodeURIComponent(product.id)}.webp" alt="" loading="lazy">`:""}<span>${esc(itemName(product))}</span></a>`:""}).join("")}</div></section>`:""}<div class="detail-actions item-detail-actions"><a class="button primary" href="${href("/calculators/crafting")}" data-link>${m.openCrafting}</a></div></div></article>`}
